<template><div class="wrap"><div v-if="profile"><div class="page-head"><div class="profile-hero"><div class="profile-big">{{profile.username?.[0]?.toUpperCase()}}</div><div><h1 style="margin:0">@{{profile.username}}</h1><p class="muted">{{profile.bio}}</p></div></div><div class="kpis"><div class="stat"><span class="muted small">Tips</span><b>{{profile.totalTips}}</b></div><div class="stat"><span class="muted small">Wins</span><b>{{profile.wins}}</b></div><div class="stat"><span class="muted small">Win rate</span><b>{{rate}}%</b></div><div class="stat"><span class="muted small">Best streak</span><b>{{profile.longestStreak||0}}</b></div></div></div><h2>Published picks</h2><div class="grid2"><PickCard v-for="p in picks" :key="p._id" :pick="p" @play="play"/></div><div v-if="!picks.length" class="empty">No published picks yet.</div></div><div v-else class="empty">Loading tipster…</div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from '../services/api';import PickCard from '../components/PickCard.vue';const route=useRoute(),router=useRouter(),profile=ref<any>(null),picks=ref<any[]>([]);const rate=computed(()=>profile.value?.totalTips?Math.round(profile.value.wins/profile.value.totalTips*1000)/10:0);function play(){router.push('/login')}onMounted(async()=>{try{const d=await api.get(`/tipsters/${route.params.username}`);profile.value=d.data.profile;picks.value=d.data.predictions}catch{}})</script>
